fn solve(mut nums: Vec<i8>) -> Vec<char> {
    // Sort the three numbers in nondecreasing order
    nums.sort_unstable();
    let a = nums[0];
    let b = nums[1];
    let c = nums[2];

    // Check the specified conditions
    let yes = 
        // at least one of the numbers is 1
        a == 1
        // at least two of the numbers are 2
        || (a == 2 && b == 2)
        // the triple is exactly (2, 4, 4)
        || (a == 2 && b == 4 && c == 4)
        // the triple is exactly (3, 3, 3)
        || (a == 3 && b == 3 && c == 3);

    if yes {
        vec!['Y', 'E', 'S']
    } else {
        vec!['N', 'O']
    }
}

